#!/usr/bin/env node
'use strict';

// Builds the two executable bundles that ship (§ 3, § 18): dist/nj.mjs from
// src/nj.ts, and dist/nj-mcp.mjs from src/nj-mcp.ts (§ 17 "MCP Interface") --
// each one everything it `require`s/`import`s under src/commands/ and
// src/core/, bundled by esbuild (DECISIONS 83: build-time tooling may choose
// its own libraries; run time still has no dependency and no
// `node_modules`). esbuild is a devDependency, required only here -- never
// by anything under src/, so it is not part of what ships.
//
// It also renders the four launchers under bin/ (§ 18, DECISIONS 187) from
// tools/wrapper.sh and tools/wrapper.cmd -- one template each, parameterised
// only by the generated file's own name (`basename "$0"` / `%~n0`) -- each
// carrying a "Generated by tools/bundle.js -- do not edit" header, and
// checks SKILL.md's frontmatter the way `agent-skills`'
// write-node-skills/scripts/build.mjs checks every Node skill's.
//
//   node tools/bundle.js           write dist/*.mjs and bin/*; fail (nothing
//                                  written) if SKILL.md's frontmatter is bad
//   node tools/bundle.js --check   build everything in memory; exit 1 unless
//                                  every one of dist/*.mjs and bin/* is
//                                  byte-identical to the committed file (and,
//                                  for bin/nj and bin/nj-mcp, executable) --
//                                  catches a stale bundle, a hand-edited
//                                  launcher, or a SKILL.md gone out of sync
//
// esbuild bundles each entry point -- unmodified, with its shebang -- and
// everything it imports under src/commands/ and src/core/, into one ESM file
// (DECISIONS 185 addendum 9b3d0de: `.mjs`, matching the other
// `agent-skills` Node skills). `platform: 'node'` externalises Node
// built-ins (`fs`, `path`, …) instead of trying to bundle them; a plugin
// below additionally normalises every externalised specifier to its
// `node:`-prefixed form and fails the build outright on any import that is
// not a recognised Node built-in -- nothing from `node_modules` ships in the
// bundle, enforced here, not merely by convention. Output is deterministic:
// no absolute paths, no timestamps (checked below, and by `--check` itself,
// which is exactly a determinism check run against the committed file).

const fs = require('fs');
const path = require('path');
const esbuild = require('esbuild');
const { builtinModules } = require('module');

const ROOT = path.resolve(__dirname, '..');
// The one version source (§ 9 "--version", D151): read here, at build
// time, and handed to esbuild's `define` below so both bundles embed the
// literal string — neither binary reads package.json at runtime.
const PKG_VERSION = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version;
const DIST_TARGETS = [
  { entry: path.join(ROOT, 'src', 'nj.ts'), out: path.join(ROOT, 'dist', 'nj.mjs') },
  { entry: path.join(ROOT, 'src', 'nj-mcp.ts'), out: path.join(ROOT, 'dist', 'nj-mcp.mjs') },
];

const WRAPPER_SH_TEMPLATE = fs.readFileSync(path.join(ROOT, 'tools', 'wrapper.sh'), 'utf8');
const WRAPPER_CMD_TEMPLATE = fs.readFileSync(path.join(ROOT, 'tools', 'wrapper.cmd'), 'utf8');
const SH_HEADER = '#!/bin/sh\n# Generated by tools/bundle.js -- do not edit.\n';
const CMD_HEADER = '@echo off\nREM Generated by tools/bundle.js -- do not edit.\n';
const WRAPPER_SH = SH_HEADER + WRAPPER_SH_TEMPLATE;
const WRAPPER_CMD = CMD_HEADER + WRAPPER_CMD_TEMPLATE;
const BIN_TARGETS = [
  { out: path.join(ROOT, 'bin', 'nj'), content: WRAPPER_SH, mode: 0o755 },
  { out: path.join(ROOT, 'bin', 'nj-mcp'), content: WRAPPER_SH, mode: 0o755 },
  { out: path.join(ROOT, 'bin', 'nj.cmd'), content: WRAPPER_CMD, mode: 0o644 },
  { out: path.join(ROOT, 'bin', 'nj-mcp.cmd'), content: WRAPPER_CMD, mode: 0o644 },
];

// node:* only (DECISIONS 185 addendum 9b3d0de): a relative/absolute import
// is left to esbuild's own resolver (it gets bundled in); anything else must
// name a real Node built-in, and is rewritten to its `node:`-prefixed form
// in the OUTPUT regardless of how the source spelled it -- so the shipped
// bundle's own import specifiers are uniformly `node:*`, never bare.
const builtins = new Set(builtinModules);
const nodeOnlyImports = {
  name: 'node-only-imports',
  setup(build) {
    build.onResolve({ filter: /.*/ }, (args) => {
      if (args.path.startsWith('.') || args.path.startsWith('/')) return null;
      const bare = args.path.startsWith('node:') ? args.path.slice(5) : args.path;
      if (!builtins.has(bare)) {
        return { errors: [{ text: `import '${args.path}' is not a node:* built-in -- the shipped bundle may import only Node built-ins` }] };
      }
      return { path: 'node:' + bare, external: true };
    });
  },
};

// esbuild only emits a file-wide 'use strict' when the ENTRY has one, and
// having emitted it, it does not re-wrap each module in its own directive --
// every module ends up sharing that ONE strict-mode scope, sloppy or not.
// A source that lacked its own 'use strict' would flip modes silently (a
// bare function's `this` becomes `undefined` instead of the global object,
// among other differences) with nothing here to say so. Every source today
// happens to start with 'use strict'; this makes that a checked contract
// instead of an accident nobody would notice breaking.
function checkStrict(files, problems) {
  for (const rel of files) {
    const abs = path.join(ROOT, rel);
    const lines = fs.readFileSync(abs, 'utf8').split('\n');
    const start = lines[0].startsWith('#!') ? 1 : 0;
    const first = (lines[start] || '').trim();
    if (first !== "'use strict';" && first !== '"use strict";') {
      problems.push(`${rel} has no leading 'use strict' -- esbuild would fold it into the entry's strict scope instead of giving it its own, silently.`);
    }
  }
}

// SKILL.md's frontmatter, checked the way write-node-skills/scripts/build.mjs
// checks every Node skill's (§ 18 "The build also checks SKILL.md"): name,
// description (<= 1024 characters), license and metadata.version (equal to
// package.json's version, compared directly -- there being no separate
// VERSION file any more to also agree with) must all be present.
function checkSkillMd(problems) {
  const skillPath = path.join(ROOT, 'SKILL.md');
  if (!fs.existsSync(skillPath)) { problems.push('SKILL.md is missing'); return; }
  const raw = fs.readFileSync(skillPath, 'utf8');
  const front = /^---\n([\s\S]*?)\n---\n/.exec(raw);
  if (!front) { problems.push('SKILL.md has no --- frontmatter ---'); return; }
  const body = front[1];
  const field = (key) => {
    const m = new RegExp(`^${key}:[ \t]*(.*)$`, 'm').exec(body);
    return m ? m[1].trim() : undefined;
  };
  const nested = (key) => {
    const m = new RegExp(`^[ \t]+${key}:[ \t]*(.*)$`, 'm').exec(body);
    return m ? m[1].trim().replace(/^["']|["']$/g, '') : undefined;
  };
  const name = field('name');
  const descRaw = field('description');
  const description = descRaw ? descRaw.replace(/^["']|["']$/g, '') : undefined;
  if (!name) problems.push('SKILL.md: name is missing');
  if (!description) problems.push('SKILL.md: description is missing');
  else if (description.length > 1024) problems.push(`SKILL.md: description has ${description.length} characters, at most 1024`);
  if (!field('license')) problems.push('SKILL.md: license is missing');
  const version = nested('version');
  if (!version) problems.push('SKILL.md: metadata.version is missing');
  else if (version !== PKG_VERSION) problems.push(`SKILL.md: metadata.version is '${version}', package.json says '${PKG_VERSION}'`);
}

const checking = process.argv.includes('--check');

async function main() {
  const problems = [];
  const distPending = []; // { rel, out, content: Buffer }
  const binPending = [];  // { rel, out, content: string, mode }

  for (const { entry, out: OUT } of DIST_TARGETS) {
    const rel = path.relative(ROOT, OUT);
    // `build` (async), not `buildSync`: esbuild refuses plugins (needed for
    // nodeOnlyImports above) in the synchronous API.
    const result = await esbuild.build({
      entryPoints: [entry],
      bundle: true,
      platform: 'node',
      format: 'esm',
      plugins: [nodeOnlyImports],
      write: false,
      logLevel: 'silent',
      // Without this, esbuild writes its `// <path>` module comments relative to
      // the invocation cwd -- three different callers (repo root, /, /tmp) built
      // three different byte sequences from the same sources. Pinned so the
      // output depends only on the sources, never on where `bundle.js` was run.
      absWorkingDir: ROOT,
      metafile: true, // gives the exact set of files actually bundled, for checkStrict
      define: { __NJ_VERSION__: JSON.stringify(PKG_VERSION) },
    });
    if (result.errors.length) {
      for (const e of result.errors) problems.push(e.text);
      continue;
    }
    checkStrict(Object.keys(result.metafile.inputs), problems);
    distPending.push({ rel, out: OUT, content: Buffer.from(result.outputFiles[0].contents) });
  }

  for (const { out: OUT, content, mode } of BIN_TARGETS) {
    binPending.push({ rel: path.relative(ROOT, OUT), out: OUT, content, mode });
  }

  checkSkillMd(problems);

  if (problems.length) {
    for (const p of problems) process.stderr.write(`bundle: ${p}\n`);
    if (!checking) process.stderr.write('bundle: nothing was written\n');
    process.exit(checking ? 1 : 2);
  }

  if (checking) {
    let staleAny = false;
    for (const { rel, out: OUT, content } of distPending) {
      let have = null;
      try { have = fs.readFileSync(OUT); } catch { /* missing counts as stale */ }
      if (!have || !have.equals(content)) {
        process.stderr.write(`bundle --check: ${rel} is STALE -- a fresh build differs. Run \`node tools/bundle.js\` and commit ${rel}.\n`);
        staleAny = true;
        continue;
      }
      process.stdout.write(`bundle --check: ${rel} is byte-identical to a fresh build\n`);
    }
    for (const { rel, out: OUT, content, mode } of binPending) {
      let have = null;
      try { have = fs.readFileSync(OUT, 'utf8'); } catch { /* missing counts as stale */ }
      if (have !== content) {
        process.stderr.write(`bundle --check: ${rel} is STALE or hand-edited -- a fresh render differs. Run \`node tools/bundle.js\` and commit ${rel}.\n`);
        staleAny = true;
        continue;
      }
      if (mode === 0o755) {
        let executable = false;
        try { executable = (fs.statSync(OUT).mode & 0o111) !== 0; } catch { /* missing, already reported above */ }
        if (!executable) {
          process.stderr.write(`bundle --check: ${rel} is not executable. Run \`node tools/bundle.js\` and commit ${rel}.\n`);
          staleAny = true;
          continue;
        }
      }
      process.stdout.write(`bundle --check: ${rel} is byte-identical to a fresh render\n`);
    }
    if (staleAny) process.exit(1);
  } else {
    for (const { rel, out: OUT, content } of distPending) {
      fs.mkdirSync(path.dirname(OUT), { recursive: true });
      fs.writeFileSync(OUT, content);
      fs.chmodSync(OUT, 0o755);
      process.stdout.write(`bundle: ${rel} written (${content.length} bytes)\n`);
    }
    for (const { rel, out: OUT, content, mode } of binPending) {
      fs.mkdirSync(path.dirname(OUT), { recursive: true });
      fs.writeFileSync(OUT, content);
      fs.chmodSync(OUT, mode);
      process.stdout.write(`bundle: ${rel} written (${content.length} bytes)\n`);
    }
  }
}

main();
